#include "resident/domains/growth/growth_model.hpp"
// 只把原付款/原Action/原Life阶段与独立逐期账绑定；临时服务没有自己的时钟或钱款状态。
#include "growth_recovery_services.hpp"
#include "growth_life_results.hpp"
#include <algorithm>
namespace hanmo::resident {
BoundGrowthPersonalRecoveryServices::BoundGrowthPersonalRecoveryServices(const CommonCatalog& common,const GrowthCatalog& growth,const GrowthRecoveryCatalog& catalog,GrowthRecoveryState& state,const GrowthRecoveryHistoryAccess& history,const GrowthRecoveryOccupationRead& occupation,const DynamicStepInput* phase):common_(common),growth_(growth),catalog_(catalog),state_(state),history_(history),occupation_(occupation),phase_(phase){}
Status BoundGrowthPersonalRecoveryServices::preview(const CommonStore& c,const StableId& actor,const GrowthQuote& quote)const{
    if(quote.command.kind!="service"||quote.command.activity!="rest")return common_success();auto valid=validate_growth_recovery_catalog(common_,growth_,catalog_);if(!valid.ok)return valid;if(!quote.context)return common_failure("GrowthRecoveryContextRequired");if(!catalog_.service_roles.find(quote.context->role_id))return common_success();if(!occupation_.current)return common_failure("GrowthRecoveryOccupationReaderRequired");
    // 原contact已核本人同处/role/可用；补军事来源完整性，使真实报价阶段就拒不可履约的疗程。
    for(const auto* id:{&actor,&quote.context->provider_actor_id}){auto clear=validate_growth_recovery_occupation_now(c,occupation_,*id,phase_);if(!clear.ok)return clear;}return common_success();
}
Outcome<GrowthQuote> BoundGrowthPersonalRecoveryServices::preview_cancel(const CommonStore& c,const GrowthState& growth,const StableId& actor,const GrowthCommand& command)const{const auto* person=c.actor(actor);const auto* action=c.action(command.action_id);const auto* service=state_.services.find(command.action_id);if(command.kind!="recovery_cancel"||!person||!person->alive||!action||!service||service->actor_id!=actor||action->actor_id!=actor||person->action_id!=command.action_id||action->kind!="service")return {false,{},common_failure("GrowthRecoveryCancellationDenied",command.action_id).error};for(const auto& row:state_.closures.rows())if(row.second.action_id==command.action_id)return {false,{},common_failure("GrowthRecoveryServiceClosed",command.action_id).error};auto progress=read_growth_recovery_progress_in_candidate(c,growth,catalog_,state_,history_,actor);if(!progress.ok)return {false,{},progress.error};GrowthQuote quote;quote.command=command;quote.data=RestCancellation{command.action_id};return {true,std::move(quote),{}};}
Outcome<GrowthEffect> BoundGrowthPersonalRecoveryServices::cancel(CommonStore& c,GrowthState& growth,const StableId& actor,const GrowthQuote& quote){auto checked=preview_cancel(c,growth,actor,quote.command);if(!checked.ok)return {false,{},checked.error};const auto* selected=std::get_if<RestCancellation>(&quote.data);if(!selected||selected->action_id!=quote.command.action_id||quote.duration||quote.cost||quote.wage)return {false,{},common_failure("StaleRecoveryCancellation").error};auto stopped=stop_growth_recovery_service_in_candidate(c,growth,catalog_,state_,history_,selected->action_id,"cancelled");if(!stopped.ok)return {false,{},stopped.error};GrowthEffect effect;effect.kind="recovery_cancel";effect.action_id=selected->action_id;for(const auto& row:state_.closures.rows())if(row.second.action_id==effect.action_id)effect.elapsed=row.second.provided_half_days;return {true,std::move(effect),{}};}
Status BoundGrowthPersonalRecoveryServices::started(CommonStore& c,GrowthState& growth,const ActionCoreView& action){return bind_growth_recovery_service_in_candidate(c,growth,common_,catalog_,state_,history_,action);}
Status BoundGrowthPersonalRecoveryServices::provided(CommonStore& c,GrowthState& growth,const ActionCoreView& action){if(!state_.services.find(action.id)){const auto* original=growth.life_activities.find(action.id);if(original&&original->view.activity=="rest"&&catalog_.service_roles.find(original->context.role_id))return common_failure("GrowthRecoveryServiceBindingMissing",action.id);return common_success();}if(!phase_)return common_failure("GrowthRecoveryPhaseRequired",action.id);auto applied=step_growth_recovery_service_in_candidate(c,growth,common_,catalog_,state_,history_,action,*phase_);return applied.ok?common_success():Status{false,{},applied.error};}
Status BoundGrowthPersonalRecoveryServices::completed(CommonStore& c,GrowthState& growth,const ActionCoreView& action){if(!state_.services.find(action.id))return common_success();if(!phase_)return common_failure("GrowthRecoveryPhaseRequired",action.id);auto applied=close_growth_recovery_service_in_candidate(c,growth,catalog_,state_,history_,action.id,"completed",{},phase_);return applied.ok?common_success():Status{false,{},applied.error};}
Status stop_growth_recovery_service_in_candidate(CommonStore& c,GrowthState& growth,const GrowthRecoveryCatalog& catalog,GrowthRecoveryState& state,const GrowthRecoveryHistoryAccess& history,const StableId& action,const StableId& reason,const StableId& cause,const DynamicStepInput* phase){if(!state.services.find(action))return common_success();for(const auto& row:state.closures.rows())if(row.second.action_id==action)return common_success();const bool dead=reason=="patient_dead"||reason=="provider_dead";if((!dead&&reason!="cancelled")||dead!=!cause.empty())return common_failure("GrowthRecoveryTerminationSourceRequired",action);const auto tick=phase?phase->to_tick:c.tick();const auto* original=growth.life_activities.find(action);if(!original||original->view.phase!=LifeActivityPhase::active)return common_failure("GrowthRecoveryOriginalTerminationRequired",action);auto stopped=cancel_life_activity(c,growth,action,tick,dead?"RecoveryParticipantDied":"ActionCancelled");if(!stopped.ok)return stopped;auto recorded=close_growth_recovery_service_in_candidate(c,growth,catalog,state,history,action,reason,cause,phase);return recorded.ok?common_success():Status{false,{},recorded.error};}
}
